```yaml
name: Publish Connectors Prerelease Command

on:
  issue_comment:
    types: [created]

permissions:
  pull-requests: write
  actions: read

jobs:
  dispatch:
    if: ${{ github.event.issue.pull_request && startsWith(github.event.comment.body, '/publish-connectors-prerelease') }}
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Get PR details
        id: pr_details
        uses: actions/github-script@v7
        with:
          script: |
            const pr = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.issue.number
            });
            core.setOutput('head_sha', pr.data.head.sha);
            core.setOutput('head_ref', pr.data.head.ref);

      - name: Post start comment
        uses: actions/github-script@v7
        with:
          script: |
            const sha = '${{ steps.pr_details.outputs.head_sha }}';
            const shortSha = sha.substring(0, 10);
            const message = `
            :rocket: **Pre-release connector build started**

            Publishing modified connectors from PR #${context.issue.number} as pre-release.

            **Expected Image Tag Format:**
            \`${{ vars.CONNECTOR_IMAGE_TAG_PREFIX }}{connector_name}:{version}-dev.${shortSha}\`

            Example: \`airbyte/source-postgres:0.1.0-dev.${shortSha}\`

            This may take a few minutes. A follow-up comment will be posted with the results.
            `;
            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              body: message
            });

      - name: Call publish connectors workflow
        id: call_publish
        uses: actions/github-script@v7
        with:
          script: |
            const response = await github.rest.actions.createWorkflowDispatch({
              owner: context.repo.owner,
              repo: context.repo.repo,
              workflow_id: 'publish_connectors.yml',
              ref: '${{ steps.pr_details.outputs.head_ref }}',
              inputs: {
                'release-type': 'pre-release',
                'modified-only': 'true'
              }
            });
            core.setOutput('run_id', response.data.id);

      - name: Wait for workflow completion
        uses: lewagon/wait-on-check-action@v1.3.4
        with:
          ref: ${{ steps.pr_details.outputs.head_sha }}
          check-name: 'Publish Connectors'
          repo-token: ${{ secrets.GITHUB_TOKEN }}
          wait-interval: 10
          max-waiting-seconds: 3600

      - name: Get workflow run status
        id: get_status
        uses: actions/github-script@v7
        with:
          script: |
            const run = await github.rest.actions.getWorkflowRun({
              owner: context.repo.owner,
              repo: context.repo.repo,
              run_id: ${{ steps.call_publish.outputs.run_id }}
            });
            core.setOutput('status', run.data.status);
            core.setOutput('conclusion', run.data.conclusion);
            core.setOutput('html_url', run.data.html_url);

      - name: Post completion comment
        uses: actions/github-script@v7
        with:
          script: |
            const status = '${{ steps.get_status.outputs.status }}';
            const conclusion = '${{ steps.get_status.outputs.conclusion }}';
            const html_url = '${{ steps.get_status.outputs.html_url }}';

            let emoji = ':hourglass_flowing_sand:';
            let title = 'In Progress';
            let body = 'The pre-release build is still running.';

            if (conclusion === 'success') {
              emoji = ':white_check_mark:';
              title = 'Pre-release build successful';
              body = `Connectors have been published successfully.

              [View workflow run](${html_url})

              You can now test the connectors using the image tags mentioned in the start comment.`;
            } else if (conclusion === 'failure') {
              emoji = ':x:';
              title = 'Pre-release build failed';
              body = `The pre-release build failed.

              [View workflow run](${html_url})

              Please check the logs for details.`;
            } else if (conclusion === 'cancelled') {
              emoji = ':stop_sign:';
              title = 'Pre-release build cancelled';
              body = `The pre-release build was cancelled.

              [View workflow run](${html_url})`;
            }

            const message = `
            ${emoji} **${title}**

            ${body}
            `;

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              body: message
            });
